E["68:3eaa6f6e"] = "Уб'йте: Багряний Коваль Молотів (Стратгольм) і принесіть його фартух."
E["68:46b74636"] = "сканування Mastercraft, якщо воно має предмет, інакше - Auctionator"
E["68:6e4cae7b"] = "Назви рецептів і матеріалів англійською, незалежно від мови вашої гри."
E["68:79e0c3f3"] = "І засновникам, які тримають своє ім'я в тіні, - теж дякуємо!"
E["68:96c9eb9e"] = "Гравці Mastercraft, які створюють, зараз у мережі на вашому сервері та у вашій фракції"
E["68:a96e127c"] = "Скільки коштує виготовлення - на сторінці «Прибуток», у підказках і на рецептах."
E["68:be0d1ca4"] = "Тут порожньо - клацніть правою кнопкою на предметі в Золото > Порадник зі здобичі, щоб додати."
E["68:cb61372e"] = "Депозит повертається після продажу - він втрачається лише якщо лот не продано."
E["69:0541a326"] = "Купувати нічого - решта у вашому банку, пошті або на альтах."
E["69:074bc5ad"] = "На 125: вивчіть «Експерт» - книга «Експертна Кулінарна Книга», 1 золото: Вулан (Спустошище)"
E["69:3c7e9244"] = "Відкрийте кожне вікно професії один раз, щоб Mastercraft дізнався ваші рецепти."
E["69:6e21be0e"] = "Клік: мітка там - стрілка веде вас, ваша карта (M) її показує."
E["69:790969d1"] = "Гравці Wowhead повідомляють, що креслення 2 ступеня випадають з босів підземель."
E["69:9b21eef6"] = "Упорядковано за тим, де вона клює першою. Наведіть на рибу, щоб побачити, де її ловити."
E["69:b48509a4"] = "ціна Auctionator, якщо він має предмет, інакше - Mastercraft"
E["69:dcff4709"] = "Спершу звільніть у сумках місце для одного предмета — туди піде предмет із другої руки."
E["69:f09425a1"] = "Рецепти зброї, доступні лише для: Зброяр - і шляхи майстрів."
